setup_icon()

w_orbit = 2.0
w_letter = 1.5
scale = 1.30
cx_src, cy_src = 40.11, 50.29


def _tx(ring: list[tuple[float, float]]) -> list[tuple[float, float]]:
    return [
        (round(50.0 + (x - cx_src) * scale, 2), round(50.0 + (y - cy_src) * scale, 2))
        for x, y in ring
    ]


